def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    df["body_mass_g"] = pd.to_numeric(
        df["body_mass_g"].astype(str).str.replace(",", "", regex=False),
        errors="coerce"
    )
    df = df[df["body_mass_g"].between(2500, 6500)]
    return df

def answer(df):
    result = {}
    for species, total in df.groupby("species", dropna=True)["body_mass_g"].sum().items():
        result[str(species)] = int(total)
    return result
